import { colors, Theme, useTheme } from '@/theme'
import { useRef, useState } from 'react'
import { TextInput, TouchableWithoutFeedback, View } from 'react-native'
import { KeyboardStickyView } from 'react-native-keyboard-controller'
import { EmailInputContainer } from './components/EmailInputContainer'
import { OTPInputContainer } from './components/OTPInputContainer'
import { useShake } from '@/utils/hooks/useShake'
import { ResendOTPButton } from './components/ResendOTPButton'
import { useBlurOnFulfill } from 'react-native-confirmation-code-field'
import * as EmailValidator from 'email-validator'
import {
	useSignUpWithMagicLinkOrRequestMagicLinkMutation,
	useRequestMagicLinkMutation
} from '@/generated/graphql'
import { defineStyles } from '@/utils/defineStyles'
import * as Haptics from 'expo-haptics'
import { Button, Grabber, ScreenTitle } from '@/components'

export type BlurOnFulfillRef = ReturnType<typeof useBlurOnFulfill>

const CONTINUE_BUTTON_OFFSET_OPEN = 12
const CONTINUE_BUTTON_OFFSET_CLOSED = 40

export const EnterEmailScreen = () => {
	const { theme } = useTheme()
	const { errorShakeStyle, shake } = useShake(10, 100)

	const [otpSent, setOtpSent] = useState(false)
	const [emailError, setEmailError] = useState('')
	const [emailInput, setEmailInput] = useState('')
	const [otpInput, setOtpInput] = useState('')
	const [otpError, setOtpError] = useState(false)

	const emailInputRef = useRef<TextInput>(null)
	const otpInputRef: BlurOnFulfillRef = useBlurOnFulfill({
		value: otpInput,
		cellCount: 6
	})
	const isEmailValid = EmailValidator.validate(emailInput)
	const [signUpWithMagicLinkOrRequestMagicLink] =
		useSignUpWithMagicLinkOrRequestMagicLinkMutation()
	const [requestMagicLink] = useRequestMagicLinkMutation()

	const handleBackgroundPress = () => {
		if (emailInputRef.current?.isFocused) {
			emailInputRef.current?.blur()
		} else if (otpInputRef.current?.isFocused) {
			otpInputRef.current?.blur()
		}
	}

	const handleEmailChange = (text: string) => {
		if (emailError) {
			setEmailError('')
		}
		setEmailInput(text)
		if (isEmailValid) {
			Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
		}
	}

	const handleEmailSubmit = () => {
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)

		if (!isEmailValid) {
			shake()
			return
		}

		emailInputRef.current?.blur()
		setEmailError('')
		signUpWithMagicLinkOrRequestMagicLink({
			variables: { input: { email: emailInput } }
		})
			.then(() => {
				setOtpSent(true)
			})
			.catch(() => {
				setEmailError('Could not sign in with this email. Please try again.')
			})
	}

	const handleResendCode = () => {
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)

		requestMagicLink({
			variables: { input: { email: emailInput, withCode: true } }
		}).then(() => {
			setOtpSent(true)
			setOtpInput('')
			setOtpError(false)
		})
	}

	return (
		<TouchableWithoutFeedback onPress={handleBackgroundPress}>
			<View style={styles.modalContainer(theme)}>
				<Grabber />
				<View style={styles.titleContainer}>
					<ScreenTitle
						title={otpSent ? 'Enter code' : 'Continue with email'}
						subtitle={
							otpSent
								? `Code sent to ${emailInput}`
								: 'Sign up or sign in with your email.' +
								  (!otpSent ? "\nWe'll send you a verification code." : '')
						}
					/>
				</View>
				{otpSent ? (
					<OTPInputContainer
						email={emailInput}
						otpInputRef={otpInputRef}
						otpInput={otpInput}
						setOtpInput={setOtpInput}
						otpError={otpError}
						setOtpError={setOtpError}
					/>
				) : (
					<EmailInputContainer
						emailInputRef={emailInputRef}
						errorShakeStyle={errorShakeStyle}
						isEmailValid={isEmailValid}
						emailInput={emailInput}
						setEmailInput={handleEmailChange}
						emailError={emailError}
					/>
				)}
				<KeyboardStickyView
					offset={{
						closed: -CONTINUE_BUTTON_OFFSET_CLOSED,
						opened: -CONTINUE_BUTTON_OFFSET_OPEN
					}}
					style={styles.continueButtonContainer}
				>
					{!otpSent ? (
						<Button
							text="Continue"
							onPress={handleEmailSubmit}
							disabled={!isEmailValid}
						/>
					) : (
						<ResendOTPButton handleResendCode={handleResendCode} />
					)}
				</KeyboardStickyView>
			</View>
		</TouchableWithoutFeedback>
	)
}

const styles = defineStyles({
	modalContainer: (theme: Theme) => ({
		flex: 1,
		paddingHorizontal: 20,
		backgroundColor: colors[theme].background
	}),
	continueButtonContainer: {
		paddingHorizontal: 20,
		position: 'absolute',
		bottom: 0,
		left: 0,
		right: 0
	},
	titleContainer: {
		marginTop: 24,
		marginBottom: 100
	}
})
